        "review.motion.motion.excels.at": "Motion Excel Dans :",
        "review.motion.project.management.complex.projects.with": "Gestion de Projet : Projets complexes avec plusieurs équipes et dépendances",
        "review.motion.team.collaboration.remote.teams.needing": "Collaboration d'Équipe : Équipes distantes ayant besoin de communication centralisée",
