function getMotionTranslation(key, lang) {
    if (motionTranslations[lang] && motionTranslations[lang][key]) {
        return motionTranslations[lang][key];
    }
    if (motionTranslations.en && motionTranslations.en[key]) {
        return motionTranslations.en[key];
    }
    return null;
}

function applyMotionTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && (key.startsWith('review.motion.') || key.startsWith('review.common.') || key.startsWith('nav.'))) {
            const translation = getMotionTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyMotionTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyMotionTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyMotionTranslations(currentLang);
}


